insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_pe3_v1'
from (values
('116.64.c.1.A',2,'In archery, the target is hit by releasing an arrow toward a bull''s-eye. Archery is classified as which type of activity?','["A target activity", "A striking and fielding activity", "An invasion game", "A rhythmic activity"]'::jsonb,0,'Target activities aim an object at a goal.','original'),
('116.64.c.1.A',2,'Disc golf is an example of which kind of activity?','["A swimming event", "A target activity", "A rhythmic activity", "A wrestling event"]'::jsonb,1,'Players throw discs at targets.','original'),
('116.64.c.1.B',2,'Which sport is a striking and fielding activity?','["Swimming", "Archery", "Softball", "Dance"]'::jsonb,2,'Softball involves striking a ball and fielding it.','original'),
('116.64.c.1.B',3,'In a striking activity, a batter keeps the eyes on the ball and shifts weight forward during the swing. This shows what?','["An illegal move", "A poor stance", "A fielding error", "Proper technique for contact and power"]'::jsonb,3,'Watching the ball and weight transfer improve contact.','original'),
('116.64.c.1.C',3,'Which activity promotes cardiorespiratory endurance and muscular strength?','["Circuit training", "Standing still", "Sitting stretches only", "A board game"]'::jsonb,0,'Circuits combine cardio and strength work.','original'),
('116.64.c.1.C',3,'A student who completes a 20-minute continuous workout at a raised heart rate is showing competency in what?','["A target activity", "A fitness activity for cardiorespiratory endurance", "A scorekeeping skill", "An officiating skill"]'::jsonb,1,'Sustained aerobic activity builds endurance.','original'),
('116.64.c.1.D',2,'Square dancing and line dancing are examples of what?','["Target activities", "Fielding activities", "Rhythmic activities", "Weight training"]'::jsonb,2,'Rhythmic activities move to a beat.','original'),
('116.64.c.1.D',3,'In a rhythmic activity, keeping steps in time with the music requires what?','["Moving at random", "Standing still", "Ignoring the music", "Following the beat and tempo"]'::jsonb,3,'Timing to the beat is essential.','original'),
('116.64.c.1.E',3,'Ultimate and pickleball are growing in popularity. Why are they called innovative games?','["They are newer activities that mix familiar skills with new rules", "They have no rules", "They cannot be played outside", "They are ancient games"]'::jsonb,0,'Innovative games blend skills in new ways.','original'),
('116.64.c.1.E',3,'A class invents a new game by combining throwing and running with a new scoring rule. What is this?','["A warm-up only", "An innovative game", "A rhythmic routine", "An officiating signal"]'::jsonb,1,'Creating a new game is innovation.','original'),
('116.64.c.2.A',3,'A player hits the same basic serve correctly seven of ten times and uses it in the match. This shows what?','["Poor strategy", "Rarely using the skill", "Performing a skill consistently", "Random luck"]'::jsonb,2,'Consistency means repeating the skill accurately.','original'),
('116.64.c.2.A',3,'Which strategy is a sound choice in a doubles match?','["Ignoring the partner", "Hitting every ball the same way", "Standing in the same spot", "Covering open space and communicating with your partner"]'::jsonb,3,'Strategy uses space and teamwork.','original'),
('116.64.c.2.B',3,'After missing a free throw short, a player notices the shot felt weak and adds more leg drive on the next try. This is an example of what?','["Using internal feedback to adjust", "Ignoring feedback", "Only external feedback", "Copying a rival"]'::jsonb,0,'The player used body sensation to adjust.','original'),
('116.64.c.2.B',3,'A coach says, "Follow through toward the target." Applying that tip is what type of feedback?','["No feedback", "External feedback", "Random feedback", "Internal feedback only"]'::jsonb,1,'A coach''s comment is external feedback.','original'),
('116.64.c.2.C',3,'Which is an appropriate practice procedure to improve a tennis serve?','["Practice only the day before a match", "Skip warm-ups", "Practice with focus, repeat the correct form and review results", "Rush through every serve"]'::jsonb,2,'Focused repetition improves skill.','original'),
('116.64.c.2.C',3,'To improve strategy in a sport, a player should do what?','["Play without thinking", "Never watch games", "Avoid learning the rules", "Study game situations and practice decisions in drills"]'::jsonb,3,'Strategy improves through study and drill.','original'),
('116.64.c.2.D',3,'In a volleyball serve, which is a critical element of success?','["Contacting the ball with a firm hand and a smooth follow-through", "Looking away", "Closing the eyes", "Hitting with a loose wrist"]'::jsonb,0,'Contact and follow-through determine accuracy.','original'),
('116.64.c.2.D',3,'Which critical element helps a bowler or pitcher deliver accurately?','["Looking away", "A consistent release point and follow-through", "Changing the release point every time", "Skipping the stance"]'::jsonb,1,'Consistent mechanics improve accuracy.','original'),
('116.64.c.2.E',3,'An official raises one arm straight overhead to signal a score. This is an example of what?','["A warm-up", "A rule change", "A hand signal used in officiating", "A foul by the player"]'::jsonb,2,'Hand signals communicate calls.','original'),
('116.64.c.2.E',3,'Which is proper officiating technique?','["Shouting at players", "Making calls without watching", "Ignoring plays", "Using clear signals and a firm, calm voice to explain the call"]'::jsonb,3,'Clear communication is key.','original'),
('116.64.c.2.F',3,'A scorekeeper must record points as they happen. Why is accuracy important?','["It ensures a fair result and correct standings", "It is optional", "It changes the rules", "It speeds up the game"]'::jsonb,0,'Accurate scoring keeps the game fair.','original'),
('116.64.c.2.F',3,'In a game where a team scores 3, 2 and 4 points in three innings, the total is how many points?','["7", "9", "8", "10"]'::jsonb,1,'3 + 2 + 4 = 9.','original'),
('116.64.c.3.A',3,'A student wants to improve her cardio for pickleball. Which goal is realistic and challenging?','["Be fit sometime", "Play once next year", "Play three 30-minute sessions a week for six weeks and track progress", "Never play"]'::jsonb,2,'A goal should be specific, measurable and time-bound.','original'),
('116.64.c.3.A',3,'Why should fitness goals be matched to the chosen skill-based activity?','["So the plan is random", "So the activity is easier to skip", "So there is no progress", "So training improves the fitness parts the activity needs"]'::jsonb,3,'Goals should serve the activity.','original'),
('116.64.c.3.B',2,'Before playing a sport, a student should do what to reduce injury?','["Warm up and use proper equipment", "Skip stretching", "Play barefoot on rough ground", "Ignore pain"]'::jsonb,0,'Warm-ups and gear protect players.','original'),
('116.64.c.3.B',3,'Which safety procedure applies when many players share a court or field?','["Run without looking", "Stay aware of others and follow the rules for boundaries", "Throw equipment at others", "Ignore the rules"]'::jsonb,1,'Awareness prevents collisions.','original'),
('116.64.c.3.C',3,'Which health benefit results from regularly playing a skill-based sport like tennis?','["Lower flexibility only", "Weaker bones", "Improved cardiorespiratory endurance and coordination", "Decreased energy"]'::jsonb,2,'Skill-based sports provide fitness benefits.','original'),
('116.64.c.3.C',3,'Playing a lifetime sport with others can also improve what?','["Only height", "Nothing", "Only sleep", "Social and emotional health"]'::jsonb,3,'Participation builds social bonds.','original'),
('116.64.c.4.A',3,'A player congratulates an opponent on a great shot. This shows what?','["Good sportsmanship", "Poor sportsmanship", "A foul", "A rule violation"]'::jsonb,0,'Acknowledging good play is sportsmanship.','original'),
('116.64.c.4.A',3,'Which is an example of acknowledging good play?','["Ignoring the point", "Saying \"nice shot\" to the other team", "Arguing the call", "Making fun of the player"]'::jsonb,1,'Positive remarks show respect.','original'),
('116.64.c.4.B',3,'Why should players accept the roles and decisions of officials?','["Officials never make calls", "So players can break rules", "It keeps the game fair and respectful", "To make the game last longer"]'::jsonb,2,'Officials enforce fair play.','original'),
('116.64.c.4.B',3,'If you disagree with a call, the best response is to do what?','["Throw the ball", "Yell at the official", "Leave the game", "Calmly accept it and keep playing"]'::jsonb,3,'Calm acceptance models sportsmanship.','original'),
('116.64.c.4.C',3,'After losing a match, a player admits the other team played better and plans to practice more. This shows what?','["Accepting performance limitations and responding with effort", "Making excuses", "Blaming officials", "Quitting"]'::jsonb,0,'Healthy acceptance leads to improvement.','original'),
('116.64.c.4.C',3,'Accepting a teammate''s mistake with encouragement helps the team because it does what?','["Increases blame", "Builds trust and morale", "Creates conflict", "Ends the game"]'::jsonb,1,'Support builds team spirit.','original'),
('116.64.c.4.D',3,'What does personal responsibility mean for creating a safe, respectful environment in a class?','["Ignoring rules", "Letting others do the work", "Following rules and treating others with respect", "Teasing others"]'::jsonb,2,'Everyone helps maintain a positive environment.','original'),
('116.64.c.4.D',3,'A student sees equipment left on the floor and puts it away. This shows what?','["Rule breaking", "Disrespect", "Carelessness", "Personal responsibility for safety"]'::jsonb,3,'Taking care of the space keeps it safe.','original'),
('116.64.c.4.E',3,'After a tough loss, which response is the healthiest?','["Review what went wrong and set a plan to improve", "Blame others", "Quit forever", "Hide your feelings"]'::jsonb,0,'A constructive response uses the setback to grow.','original'),
('116.64.c.4.E',3,'How should a player respond to a big win?','["Brag loudly", "Celebrate respectfully without taunting opponents", "Ignore teammates", "Mock the other team"]'::jsonb,1,'Respectful celebration is sportsmanship.','original'),
('116.64.c.5.A',2,'Which choice supports lifelong physical activity?','["Avoiding all sports", "Doing one workout a year", "Choosing a skill-based activity you enjoy and can keep doing", "Only watching sports"]'::jsonb,2,'Enjoyable activities are easier to continue.','original'),
('116.64.c.5.A',2,'Why would a student pick one skill-based lifetime activity to participate in regularly?','["To avoid activity", "To quit quickly", "To lower fitness", "To build skill, fitness and enjoyment over time"]'::jsonb,3,'Regular participation builds skill and fitness.','original'),
('116.64.c.5.B',3,'Why is sleep important for athletes in skill-based sports?','["It supports recovery, reaction time and learning of skills", "It lowers skill", "It is not important", "It reduces focus"]'::jsonb,0,'Sleep helps performance and recovery.','original'),
('116.64.c.5.B',3,'A player who sleeps only a few hours before a tournament will likely have what?','["More endurance", "Slower reactions and lower performance", "Better accuracy", "Faster reactions"]'::jsonb,1,'Sleep loss harms performance.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
